bull_r1, bear_r1, bull_r2, bear_r2, bull_r3, bear_r3 = args
rounds = [(bull_r1, bear_r1), (bull_r2, bear_r2), (bull_r3, bear_r3)]
lines = []
for idx, (bull, bear) in enumerate(rounds, start=1):
    lines.append(f"\n## Round {idx}")
    if bull:
        lines.append(f"**Bull Researcher:** {bull}")
    if bear:
        lines.append(f"**Bear Researcher:** {bear}")
return "\n".join(lines)

